// TrafficLight: switch-based hierarchical state machine generated by MachinaState.
// Do not edit by hand. Derive from this class and implement the guard and action hooks.
#pragma once

#include <cstddef>

namespace Demo {

    class TrafficLight {
      public:
        enum class State {
            Off,
            Operating,
            Red,   // in Operating
            Green,   // in Operating
            Yellow,   // in Operating
            Flashing,
            None
        };

        enum class Event {
            Timer,
            PedestrianRequest,
            PowerOn,
            PowerOff,
            Fault,
            Repair
        };

        enum class TraceKind {
            Start,        // name = machine name
            Event,        // name = event being dispatched
            Ignored,      // name = event no state handled
            Transition,   // name = "Source -> Target"
            Exit,         // name = state being exited
            Enter         // name = state being entered
        };

        static constexpr std::size_t kStateCount  = 6;
        static constexpr std::size_t kEventCount  = 6;
        static constexpr std::size_t kRegionCount = 2;   // region 0 is the top level
        static constexpr std::size_t kQueueCapacity = 16;

        virtual ~TrafficLight() = default;

        // Resets the machine (running timers are cancelled, history is forgotten) and enters the initial state configuration.
        void Start() {
            const ScopedLock lock(*this);
            for (State& state : active_) {
                state = State::None;
            }
            for (State& state : history_) {
                state = State::None;
            }
            queueHead_  = 0;
            queueCount_ = 0;
            Trace(TraceKind::Start, "TrafficLight");
            EnterDown(State::None, State::Off, false);
            DrainQueue();
        }

        // Dispatches an event to the innermost active states first. Returns false if the event was not handled.
        bool Dispatch(Event event) {
            const ScopedLock lock(*this);
            const bool handled = DispatchCore(event);
            DrainQueue();
            return handled;
        }

        // Innermost active state (following the first region of orthogonal states).
        State Current() const {
            const ScopedLock lock(*this);
            return Innermost(active_[0]);
        }

        // True if the given state is active.
        bool IsIn(State state) const {
            const ScopedLock lock(*this);
            return state != State::None && active_[RegionOf(state)] == state;
        }

        // True once a top-level final state has been reached.
        bool IsFinished() const {
            const ScopedLock lock(*this);
            return false;
        }

        static State ParentOf(State state) {
            switch (state) {
                case State::Red:
                case State::Green:
                case State::Yellow:
                    return State::Operating;
                default:
                    return State::None;
            }
        }

        static const char* StateName(State state) {
            switch (state) {
                case State::Off:
                    return "Off";
                case State::Operating:
                    return "Operating";
                case State::Red:
                    return "Red";
                case State::Green:
                    return "Green";
                case State::Yellow:
                    return "Yellow";
                case State::Flashing:
                    return "Flashing";
                default:
                    return "None";
            }
        }

        static const char* EventName(Event event) {
            switch (event) {
                case Event::Timer:
                    return "Timer";
                case Event::PedestrianRequest:
                    return "PedestrianRequest";
                case Event::PowerOn:
                    return "PowerOn";
                case Event::PowerOff:
                    return "PowerOff";
                case Event::Fault:
                    return "Fault";
                case Event::Repair:
                    return "Repair";
                default:
                    return "";
            }
        }

      protected:
        // Mutual exclusion around every public member, e.g. backed by a mutable std::mutex.
        // Hooks must not call public members of this class unless the lock is recursive.
        virtual void Lock() const   = 0;
        virtual void Unlock() const = 0;
        // Override to log state machine activity.
        virtual void Trace(TraceKind kind, const char* name) {
            (void)kind;
            (void)name;
        }
        // Queues an event from inside a hook; it is processed after the current event. Returns false if the queue is full.
        bool Post(Event event) {
            QueuedEvent entry {};
            entry.event = event;
            return Enqueue(entry);
        }
        // Actions
        virtual void redOn() = 0;
        virtual void redOff() = 0;
        virtual void greenOn() = 0;
        virtual void greenOff() = 0;
        virtual void yellowOn() = 0;
        virtual void yellowOff() = 0;
        virtual void flashOn() = 0;
        virtual void flashOff() = 0;
        virtual void logFault() = 0;
        virtual void shortenGreen() = 0;

      private:
        class ScopedLock {
          public:
            explicit ScopedLock(const TrafficLight& owner) : owner_(owner) {
                owner_.Lock();
            }
            ~ScopedLock() {
                owner_.Unlock();
            }
            ScopedLock(const ScopedLock&)            = delete;
            ScopedLock& operator=(const ScopedLock&) = delete;

          private:
            const TrafficLight& owner_;
        };

        struct QueuedEvent {
            Event event;
        };

        bool Enqueue(const QueuedEvent& entry) {
            if (queueCount_ == kQueueCapacity) {
                return false;
            }
            queue_[(queueHead_ + queueCount_) % kQueueCapacity] = entry;
            ++queueCount_;
            return true;
        }

        void DrainQueue() {
            while (queueCount_ > 0) {
                const QueuedEvent entry = queue_[queueHead_];
                queueHead_              = (queueHead_ + 1) % kQueueCapacity;
                --queueCount_;
                DispatchCore(entry.event);
            }
        }

        bool DispatchCore(Event event) {
            Trace(TraceKind::Event, EventName(event));
            if (active_[0] != State::None && DispatchState(active_[0], event)) {
                return true;
            }
            Trace(TraceKind::Ignored, EventName(event));
            return false;
        }

        // Offers the event to every active region below `state` first, then to `state` itself.
        bool DispatchState(State state, Event event) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                if (active_[region] != State::None && DispatchState(active_[region], event)) {
                    return true;
                }
            }
            return HandleEvent(state, event);
        }

        bool HandleEvent(State state, Event event) {
            switch (state) {
                case State::Off:
                    switch (event) {
                        case Event::PowerOn:
                            Trace(TraceKind::Transition, "Off -> Operating");
                            ExitState(State::Off);
                            EnterDown(State::None, State::Operating, false);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Operating:
                    switch (event) {
                        case Event::PowerOff:
                            Trace(TraceKind::Transition, "Operating -> Off");
                            ExitState(State::Operating);
                            EnterDown(State::None, State::Off, false);
                            return true;
                        case Event::Fault:
                            Trace(TraceKind::Transition, "Operating -> Flashing");
                            ExitState(State::Operating);
                            logFault();
                            EnterDown(State::None, State::Flashing, false);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Red:
                    switch (event) {
                        case Event::Timer:
                            Trace(TraceKind::Transition, "Red -> Green");
                            ExitState(State::Red);
                            EnterDown(State::Operating, State::Green, false);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Green:
                    switch (event) {
                        case Event::Timer:
                            Trace(TraceKind::Transition, "Green -> Yellow");
                            ExitState(State::Green);
                            EnterDown(State::Operating, State::Yellow, false);
                            return true;
                        case Event::PedestrianRequest:
                            Trace(TraceKind::Transition, "Green (internal)");
                            shortenGreen();
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Yellow:
                    switch (event) {
                        case Event::Timer:
                            Trace(TraceKind::Transition, "Yellow -> Red");
                            ExitState(State::Yellow);
                            EnterDown(State::Operating, State::Red, false);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Flashing:
                    switch (event) {
                        case Event::PowerOff:
                            Trace(TraceKind::Transition, "Flashing -> Off");
                            ExitState(State::Flashing);
                            EnterDown(State::None, State::Off, false);
                            return true;
                        case Event::Repair:
                            Trace(TraceKind::Transition, "Flashing -> Operating (history)");
                            ExitState(State::Flashing);
                            EnterDown(State::None, State::Operating, true);
                            return true;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }
            return false;
        }

        static std::size_t RegionOf(State state) {
            switch (state) {
                case State::Red:
                case State::Green:
                case State::Yellow:
                    return 1;
                default:
                    return 0;
            }
        }

        static std::size_t FirstRegionOf(State state) {
            switch (state) {
                case State::Operating:
                    return 1;
                default:
                    return 0;
            }
        }

        static std::size_t RegionsOf(State state) {
            switch (state) {
                case State::Operating:
                    return 1;
                default:
                    return 0;
            }
        }

        void EnterRegion(std::size_t region) {
            switch (region) {
                case 1:
                    EnterDown(State::Operating, State::Red, false);
                    break;
                default:
                    break;
            }
        }

        void OnEntry(State state) {
            switch (state) {
                case State::Red:
                    redOn();
                    break;
                case State::Green:
                    greenOn();
                    break;
                case State::Yellow:
                    yellowOn();
                    break;
                case State::Flashing:
                    flashOn();
                    break;
                default:
                    break;
            }
        }

        void OnExit(State state) {
            switch (state) {
                case State::Red:
                    redOff();
                    break;
                case State::Green:
                    greenOff();
                    break;
                case State::Yellow:
                    yellowOff();
                    break;
                case State::Flashing:
                    flashOff();
                    break;
                default:
                    break;
            }
        }

        void ExitState(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first + RegionsOf(state); region-- > first;) {
                if (active_[region] != State::None) {
                    ExitState(active_[region]);
                }
            }
            Trace(TraceKind::Exit, StateName(state));
            OnExit(state);
            active_[RegionOf(state)] = State::None;
            history_[RegionOf(state)] = state;   // last state exited from its region
        }

        // Enters every state from below `from` down to `target`, then follows default (initial) transitions
        // or, with `history`, restores the configuration recorded below `target`.
        void EnterDown(State from, State target, bool history) {
            State state = target;
            State next  = State::None;
            while (ParentOf(state) != from) {
                next  = state;
                state = ParentOf(state);
            }
            EnterState(state);
            if (next == State::None) {
                if (history) {
                    EnterHistory(state, false);
                    return;
                }
                EnterDefault(state);
                return;
            }
            EnterDown(state, target, history);
        }

        void EnterState(State state) {
            active_[RegionOf(state)] = state;
            Trace(TraceKind::Enter, StateName(state));
            OnEntry(state);
        }

        void EnterDefault(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                EnterRegion(region);
            }
        }

        // Restores the regions of `state` from the states last exited from them (recursively for deep history).
        void EnterHistory(State state, bool deep) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                const State remembered = history_[region];
                if (remembered == State::None) {
                    EnterRegion(region);
                } else if (deep) {
                    EnterState(remembered);
                    EnterHistory(remembered, true);
                } else {
                    EnterDown(state, remembered, false);
                }
            }
        }

        State Innermost(State state) const {
            while (state != State::None && RegionsOf(state) > 0 && active_[FirstRegionOf(state)] != State::None) {
                state = active_[FirstRegionOf(state)];
            }
            return state;
        }

        State active_[kRegionCount] = { State::None, State::None };   // active state per region
        State history_[kRegionCount] = { State::None, State::None };   // state last exited per region
        QueuedEvent queue_[kQueueCapacity] = {};
        std::size_t queueHead_  = 0;
        std::size_t queueCount_ = 0;
    };
}
